//! Generates `include/csk.h` from the `extern "C"` surface. The header is
//! checked in; CI fails if a build changes it.

fn main() {
    let dir = std::env::var("CARGO_MANIFEST_DIR").expect("manifest dir");
    println!("cargo:rerun-if-changed=src");
    let config = cbindgen::Config {
        language: cbindgen::Language::C,
        include_guard: Some("CSK_H".into()),
        header: Some(
            "/* ClearSkies engine C ABI. Generated by cbindgen from native/crates/csk-ffi; do not edit. */".into(),
        ),
        cpp_compat: true,
        usize_is_size_t: true,
        style: cbindgen::Style::Both,
        ..Default::default()
    };
    cbindgen::Builder::new()
        .with_crate(&dir)
        .with_config(config)
        .generate()
        .expect("cbindgen")
        .write_to_file(format!("{dir}/include/csk.h"));
}
